 // A held-out corpus checks deployed C++ inference, not the Python training model.
 check(argc==2,"holdout file argument");std::ifstream f(argv[1],std::ios::binary);check(f.good(),"holdout readable");double mse=0,neuralLoss=0,defaultLoss=0;int rows=0,neuralWins=0;nova::Engine predictor;predictor.prepare(22050);nova::FeatureExtractor predictorFeatures;std::array<float,155> x{};nova::Genes y;
