  nova::FitTarget t;t.note=static_cast<int>(std::round(x[153]*24+60));t.rate=22050;t.left.resize(static_cast<size_t>(std::round(x[154]*3*t.rate)));t.right=t.left;t.gate=t.left.size()/t.rate*.7;
