 double phase=0;for(size_t i=0;i<target.left.size();++i){double t=i/target.rate;phase+=2*nova::pi*220*(1+.015*std::sin(2*nova::pi*5*t))/target.rate;target.left[i]=target.right[i]=static_cast<float>(.3*std::sin(phase)*(1-std::exp(-t*80)));}
 std::atomic<bool> cancel{false};auto m=nova::estimatePartials(target,cancel);check(m.valid()&&m.tracked,"tracked model valid");bool movement=false;int fundamental=-1;for(int j=0;j<m.count;++j)if(std::abs(m.partials[j].frequency-220)<20){fundamental=j;const auto& track=m.partials[j].frequencyRatio;auto range=std::minmax_element(track.begin()+8,track.end()-8);movement=*range.second-*range.first>.012f;break;}check(movement,"vibrato tracked");
 auto bytes=nova::encodeModel(m);nova::SpectralModel restored;check(nova::decodeModel(bytes.data(),bytes.size(),restored),"new model round trip");check(restored.partials[fundamental].frequencyRatio==m.partials[fundamental].frequencyRatio&&restored.noise==m.noise,"trajectories and residual saved exactly");check(!nova::decodeModel(bytes.data(),bytes.size()-4,restored),"truncation rejected");auto corrupt=m;corrupt.noise[1][1]=NAN;check(!corrupt.valid()&&nova::encodeModel(corrupt).empty(),"bad noise rejected");corrupt=m;corrupt.partials[0].frequencyRatio[2]=NAN;check(!corrupt.valid(),"bad trajectory rejected");
 // Legacy V1 migration: 20 envelope points must preserve an old fixed-frequency patch.
