 auto ai=nova::fitNativeParameters(target,nova::preset(0),8,cancel,{},-1,true);check(ai.valid&&ai.neuralUsed,"neural candidates evaluated");auto noai=nova::fitNativeParameters(target,nova::preset(0),8,cancel,{},-1,false);check(noai.valid&&!noai.neuralUsed,"neural switch bypasses model");
